<script setup>definePageMeta({middleware:['auth','admin']});const {data:users}=await useFetch('/api/admin/users');const f=reactive({title:'',body:'',attachmentUrl:'',passingScore:80,targetIds:[],questions:[{question:'',options:['','','',''],correct:0}]});function addQ(){f.questions.push({question:'',options:['','','',''],correct:0})}async function save(){await $fetch('/api/admin/cards',{method:'POST',body:f});navigateTo('/admin')}</script><template><main class="max-w-4xl mx-auto p-7"><form class="panel space-y-5" @submit.prevent="save"><h1 class="text-3xl font-black">Buat Card</h1><input v-model="f.title" class="input" placeholder="Judul card" required><textarea v-model="f.body" class="input" rows="6" placeholder="Isi informasi" required></textarea><input v-model="f.attachmentUrl" class="input" placeholder="URL lampiran/file (PDF, gambar, Word, Excel, SVG, link)"><label>Nilai kelulusan <input v-model.number="f.passingScore" type="number" min="0" max="100" class="input"></label><fieldset><legend class="font-black">Target prioritas</legend><label v-for="u in users?.users" class="inline-block mr-4"><input type="checkbox" :value="u.id" v-model="f.targetIds"> {{u.name}}</label></fieldset><fieldset v-for="(q,qi) in f.questions" class="border rounded-xl p-4"><input v-model="q.question" class="input" :placeholder="`Pertanyaan ${qi+1}`" required><div class="grid md:grid-cols-2 gap-2 mt-2"><label v-for="(_,oi) in q.options" class="flex gap-2 items-center"><input type="radio" :name="`correct${qi}`" :value="oi" v-model="q.correct"><input v-model="q.options[oi]" class="input" :placeholder="`Pilihan ${oi+1}`" required></label></div></fieldset><button type="button" class="btn bg-slate-100" @click="addQ">+ Pertanyaan</button><button class="btn-primary w-full">Done / Post & kirim notifikasi</button></form></main></template>